package kik.qa;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.Callable;import org.json.*;import kik.i18n.*;
/** Disposable local profile verifies new source isolation without changing the owner's records. */
public final class SourcesAudit extends Instrumentation {
 Context c;String original,list,p;Activity activity;int checks;
 void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks++;}
 Object call(String name,Class<?>[] types,Object... args)throws Exception{Method m=Class.forName("kik.i18n.FreeSources").getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(null,args);}
 <T>T ui(Callable<T> f){Object[] o=new Object[2];runOnMainSync(()->{try{o[0]=f.call();}catch(Throwable e){o[1]=e;}});if(o[1]!=null)throw new RuntimeException((Throwable)o[1]);return (T)o[0];}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){boolean passed=false;String error="";c=getTargetContext();original=ProfileStore.current(c);list=c.getSharedPreferences("kik_profiles",0).getString("list","[]");try{
 String link="https://uaserials.com/12740-unabomber-2026.html";
 Method norm=Progress.class.getDeclaredMethod("norm",String.class);norm.setAccessible(true);check("source_namespace",norm.invoke(null,link).equals("uaserials/12740-unabomber-2026.html"));check("old_namespace_unchanged",norm.invoke(null,"https://hdrezka.sh/films/drama/1-test.html").equals("films/drama/1-test.html"));
 p=ProfileStore.create(c,"QA Sources","Sources6789").id;c.getSharedPreferences("kik_profiles",0).edit().putString("current",p).commit();ProfileStore.picked=true;ProfileStore.completeTasteSetup(c,p);
 check("new_source_watchlist",Progress.toggleLater(c,link,"QA Ukrainian source",null,"2026","Драма"));check("new_profile_isolated",Progress.later(c,original).toString().indexOf("QA Ukrainian source")<0);check("watchlist_canonical_url",Progress.later(c).getJSONObject(0).getString("link").equals(link));
 List<Site.Card> cards=(List<Site.Card>)call("cards",new Class[]{String.class},new Object[]{null});check("live_ukrainian_catalogue",cards.size()>5);check("catalogue_domain",cards.get(0).link.startsWith("https://uaserials.com/"));
 Site.Film film=Site.film(link);check("live_ukrainian_film",film.title.length()>0);check("external_source_is_explicit",link.equals(film.sourceUrl));check("no_fake_playback_voices",film.voices.isEmpty());
 Method parse=Site.class.getDeclaredMethod("parseFilm",String.class,String.class);parse.setAccessible(true);Site.Film fixture=(Site.Film)parse.invoke(null,"https://hdrezka.sh/series/drama/646-vo-vse-tyazhkie-2008.html","<h1>Breaking Bad</h1><a href=\"https://www.imdb.com/title/tt0903747/\">IMDb</a>");check("imdb_parsed",fixture.imdb.equals("tt0903747"));call("enrich",new Class[]{Site.Film.class},fixture);check("metadata_reaches_native",fixture.metadataCredit!=null&&fixture.metadataCredit.contains("TMDB"));check("ukrainian_title_reaches_native",!fixture.title.equals("Breaking Bad"));
 activity=startActivitySync(new Intent(c,FilmActivity.class).putExtra("link",link).putExtra("title","QA Ukrainian source").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field w=FilmActivity.class.getDeclaredField("watch");w.setAccessible(true);long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end&&!ui(()->((Button)w.get(activity)).isEnabled()))SystemClock.sleep(250);check("external_button_enabled",ui(()->((Button)w.get(activity)).isEnabled()));check("external_button_label",ui(()->((Button)w.get(activity)).getText().toString().contains("UASerials")));check("external_open_not_fake_history",Progress.recent(c).isEmpty());passed=true;
 }catch(Throwable e){error=e.toString();}finally{try{if(activity!=null)ui(()->{activity.finish();return null;});c.getSharedPreferences("kik_profiles",0).edit().putString("current",original).commit();if(p!=null)ProfileStore.delete(c,p);c.getSharedPreferences("kik_profiles",0).edit().putString("list",list).putString("current",original).commit();}catch(Exception e){passed=false;error=e.toString();}Bundle out=new Bundle();out.putString("stream","Sources audit passed="+passed+" checks="+checks+" "+error);finish(passed?-1:0,out);}}
}
